      "tipo": "GC",
      "causa_raiz": "Alocação excessiva de memória gerenciada (~7.98 MB no frame 1915), disparando a coleta do Garbage Collector com uma pausa de 24.57 ms. Isso quase consome o orçamento total do frame de 28.6 ms, causando engasgos (hitch/stutter) na taxa de quadros.",
      "codigo_refatorado": "using System.Collections.Generic; using UnityEngine;  public class ObjectPoolManager : MonoBehaviour {     [System.Serializable]     public struct PoolConfig {         public GameObject prefab;         public int initialSize;     }      [SerializeField] private List<PoolConfig> poolsToPreload;     private readonly Dictionary<GameObject, Queue<GameObject>> _poolDictionary = new Dictionary<GameObject, Queue<GameObject>>();      private void Awake() {         foreach (var config in poolsToPreload) {             Preload(config.prefab, config.initialSize);         }     }      public void Preload(GameObject prefab, int count) {         if (!_poolDictionary.ContainsKey(prefab)) {             _poolDictionary[prefab] = new Queue<GameObject>(count);         }         for (int i = 0; i < count; i++) {             GameObject obj = Instantiate(prefab, transform);             obj.SetActive(false);             _poolDictionary[prefab].Enqueue(obj);         }     }      public GameObject Get(GameObject prefab, Vector3 position, Quaternion rotation) {         if (!_poolDictionary.TryGetValue(prefab, out var queue) || queue.Count == 0) {             GameObject newObj = Instantiate(prefab, position, rotation, transform);             return newObj;         }         GameObject obj = queue.Dequeue();         obj.transform.SetPositionAndRotation(position, rotation);         obj.SetActive(true);         return obj;     }      public void Release(GameObject prefab, GameObject obj) {         obj.SetActive(false);         if (!_poolDictionary.ContainsKey(prefab)) {             _poolDictionary[prefab] = new Queue<GameObject>();         }         _poolDictionary[prefab].Enqueue(obj);     } }",
      "explicacao_didatica": "Quando usamos 'Instantiate' e 'Destroy' repetidamente ou criamos grandes estruturas temporárias (como listas ou arrays novos a todo momento), a Unity aloca memória no Heap. O Garbage Collector precisa interromper a execução do jogo para limpar essa sujeira acumulada, gerando congelamentos na tela. Usando a técnica de 'Object Pooling' (reutilização de objetos já criados), mantemos instâncias inativas prontas para uso, reduzindo a alocação de memória a quase zero durante o gameplay."
    }
  ],
  "dicas_level_design": null
}

